from typing import List

class Solution:
    def closestRoom(self, rooms: List[List[int]], queries: List[List[int]]) -> List[int]:
        res = []
        for pref, mn in queries:
            best, bestDiff = -1, float('inf')
            for rid, size in rooms:
                if size < mn:
                    continue
                diff = abs(rid - pref)
                if diff < bestDiff or (diff == bestDiff and rid < best):
                    best, bestDiff = rid, diff
            res.append(best)
        return res

