class Solution {
public:
    vector<int> closestRoom(vector<vector<int>>& rooms, vector<vector<int>>& queries) {
        vector<int> res;
        res.reserve(queries.size());
        for (auto& q : queries) {
            int pref = q[0], mn = q[1];
            int best = -1;
            long long bestDiff = LLONG_MAX;
            for (auto& r : rooms) {
                if (r[1] < mn) continue;
                long long diff = abs((long long)r[0] - pref);
                if (diff < bestDiff || (diff == bestDiff && r[0] < best)) {
                    best = r[0];
                    bestDiff = diff;
                }
            }
            res.push_back(best);
        }
        return res;
    }
};

