class Solution {
public:
    vector<int> closestRoom(vector<vector<int>>& rooms, vector<vector<int>>& queries) {
        sort(rooms.begin(), rooms.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[1] > b[1];
        });
        int k = queries.size();
        vector<int> order(k);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) {
            return queries[a][1] > queries[b][1];
        });
        set<int> ids;
        vector<int> res(k, -1);
        int i = 0, n = rooms.size();
        for (int j : order) {
            int pref = queries[j][0], mn = queries[j][1];
            while (i < n && rooms[i][1] >= mn) ids.insert(rooms[i++][0]);
            auto it = ids.lower_bound(pref);
            int best = -1;
            long long bestDiff = LLONG_MAX;
            auto consider = [&](int cand) {
                long long diff = llabs((long long)cand - pref);
                if (best == -1 || diff < bestDiff || (diff == bestDiff && cand < best)) {
                    best = cand;
                    bestDiff = diff;
                }
            };
            if (it != ids.end()) consider(*it);
            if (it != ids.begin()) consider(*prev(it));
            res[j] = best;
        }
        return res;
    }
};

