import java.util.*;

class Solution {
    public int[] closestRoom(int[][] rooms, int[][] queries) {
        Arrays.sort(rooms, (a, b) -> b[1] - a[1]);
        Integer[] order = new Integer[queries.length];
        for (int i = 0; i < order.length; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> queries[b][1] - queries[a][1]);
        TreeMap<Integer, Integer> ids = new TreeMap<>();
        int[] res = new int[queries.length];
        Arrays.fill(res, -1);
        int i = 0, n = rooms.length;
        for (int j : order) {
            int pref = queries[j][0], mn = queries[j][1];
            while (i < n && rooms[i][1] >= mn) {
                ids.put(rooms[i][0], rooms[i][0]);
                i++;
            }
            int best = -1;
            long bestDiff = Long.MAX_VALUE;
            Integer up = ids.ceilingKey(pref);
            Integer down = ids.floorKey(pref);
            if (up != null) {
                best = up;
                bestDiff = Math.abs((long) up - pref);
            }
            if (down != null) {
                long diff = Math.abs((long) down - pref);
                if (best == -1 || diff < bestDiff || (diff == bestDiff && down < best)) {
                    best = down;
                    bestDiff = diff;
                }
            }
            res[j] = best;
        }
        return res;
    }
}

