/**
 * @param {number[][]} rooms
 * @param {number[][]} queries
 * @return {number[]}
 */
var closestRoom = function(rooms, queries) {
    rooms.sort((a, b) => b[1] - a[1]);
    const k = queries.length;
    const order = [...Array(k).keys()].sort((a, b) => queries[b][1] - queries[a][1]);
    const ids = [];
    const lowerBound = (arr, x) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };
    const res = new Array(k).fill(-1);
    let i = 0;
    for (const j of order) {
        const pref = queries[j][0], mn = queries[j][1];
        while (i < rooms.length && rooms[i][1] >= mn) {
            const p = lowerBound(ids, rooms[i][0]);
            ids.splice(p, 0, rooms[i][0]);
            i++;
        }
        const pos = lowerBound(ids, pref);
        let best = -1, bestDiff = Infinity;
        const consider = (cand) => {
            const diff = Math.abs(cand - pref);
            if (diff < bestDiff || (diff === bestDiff && cand < best)) {
                best = cand;
                bestDiff = diff;
            }
        };
        if (pos < ids.length) consider(ids[pos]);
        if (pos > 0) consider(ids[pos - 1]);
        res[j] = best;
    }
    return res;
};
